using Microsoft.CodeAnalysis;

namespace Passenger.Analyzers;

/// <summary>The attributes PSG0001 reads (<see cref="IdentifierLiterals"/>), given to every compilation as embedded types, so
/// each assembly has its own and none sees another's.</summary>
[Generator(LanguageNames.CSharp)]
public sealed class IdentifierAttributes : IIncrementalGenerator
{
    public const string Home = "IdentifierHomeAttribute";
    public const string Of = "IdentifierOfAttribute";

    private const string Source = """
        // <auto-generated/>
        namespace Passenger
        {
            /// <summary>A home of identifiers: a type whose every const string is one, or a single const that is one. Each
            /// is written here alone and named from here elsewhere (PSG0001).</summary>
            [global::Microsoft.CodeAnalysis.Embedded]
            [global::System.AttributeUsage(global::System.AttributeTargets.Class | global::System.AttributeTargets.Struct
                | global::System.AttributeTargets.Field, Inherited = false)]
            internal sealed class IdentifierHomeAttribute : global::System.Attribute
            {
            }

            /// <summary>A parameter, property or field that takes the identifiers of a home's type: one of them written as
            /// text where it is given or compared is flagged however plain a word it is (PSG0001).</summary>
            [global::Microsoft.CodeAnalysis.Embedded]
            [global::System.AttributeUsage(global::System.AttributeTargets.Parameter | global::System.AttributeTargets.Property
                | global::System.AttributeTargets.Field, Inherited = false)]
            internal sealed class IdentifierOfAttribute : global::System.Attribute
            {
                public IdentifierOfAttribute(global::System.Type home)
                {
                }
            }
        }
        """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(output =>
        {
            output.AddEmbeddedAttributeDefinition();
            output.AddSource("IdentifierAttributes.g.cs", Source);
        });
    }
}
